"use strict";
const stores=[{id:'target',name:'Target',mark:'target',detail:'Little adventures, big imaginations'},{id:'lego',name:'LEGO Store',mark:'lego',detail:'A world they can build'},{id:'books',name:'Barnes & Noble',mark:'book',detail:'Wonder, stories, and discovery'}];
const gifts=[
{id:'tiles',store:'lego',name:'Winter Castle Building Set',category:'Build & Play',age:'5+',price:39.99,short:'A castle with a thousand possible stories.',detail:'Stack colorful magnetic pieces into towers, secret rooms, and bridges. Every day, a different kingdom.',inside:'48 magnetic pieces and a build guide',play:'Can you build a bridge wide enough for a reindeer?'},
{id:'train',store:'target',name:'Little Timber Train',category:'Build & Play',age:'3+',price:29.99,short:'Next stop: absolutely anywhere.',detail:'Connect the carriages, lay a winding track, and take the little red engine somewhere only you can imagine.',inside:'An engine, 2 carriages, and 12 wooden tracks',play:'Make a station out of blocks and give your train a snowy place to stop.'},
{id:'bunny',store:'target',name:'Marshmallow Bunny',category:'Cozy & Creative',age:'3+',price:19.99,short:'Some adventures start with a cuddle.',detail:'Velvety ears, a tiny scarf, and a very important job: keeping you company through every story and dream.',inside:'One 12-inch plush bunny with a stitched scarf',play:'What will you name your new story-time friend?'},
{id:'art',store:'books',name:'Little Studio Watercolor Kit',category:'Cozy & Creative',age:'5+',price:24.99,short:'Paint the world the way you see it.',detail:'Open the little tin, dip your brush, and turn a blank page into a winter forest, a dragon, or a whole new world.',inside:'12 colors, 2 brushes, and 10 watercolor sheets',play:'Can you paint snow using blue and purple?'},
{id:'telescope',store:'books',name:'Starlight Telescope',category:'Discover',age:'7+',price:54.99,short:'The universe is waiting up for you.',detail:'Set your telescope on a steady table, point it at the Moon, and discover craters that look like another world. Explore with a grown-up; never look at the Sun.',inside:'A telescope, tabletop tripod, and Moon guide',play:'Draw the Moon tonight. Will it look the same next week?'},
{id:'truck',store:'target',name:'Trailblazer RC Truck',category:'Discover',age:'6+',price:44.99,short:'Turn the living room into the wild.',detail:'Rumble over rugs and climb cushion mountains. Big rubber tires and a four-way controller put your next adventure in your hands.',inside:'RC truck, controller, and rechargeable truck battery',play:'Build a trail with a tunnel and a hill. Where will it lead?'}];
const icons={spark:'<path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6Z"/>',globe:'<circle cx="12" cy="10" r="7"/><path d="M8 17v3m8-3v3M5 21h14M7 12l3-3 3 2 4-4"/>',book:'<path d="M12 6v14m0-14c-3-3-7-2-9-2v14c4-1 7 0 9 2 2-2 5-3 9-2V4c-2 0-6-1-9 2Z"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/>',bag:'<path d="M4 8h16l1 13H3L4 8Zm5 0V6a3 3 0 0 1 6 0v2"/>',heart:'<path d="M20.8 8.6c0 4.3-8.8 9.8-8.8 9.8S3.2 12.9 3.2 8.6a4.4 4.4 0 0 1 8.8-.2 4.4 4.4 0 0 1 8.8.2Z"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/>',lego:'<path d="M4 9h16v11H4zM7 9V5h4v4m2 0V5h4v4"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v1a7 7 0 0 0 14 0v-1m-7 8v4m-3 0h6"/>',sound:'<path d="m3 9 4 0 5-4v14l-5-4H3Zm13-2a7 7 0 0 1 0 10m3-13a11 11 0 0 1 0 16"/>',rotate:'<path d="M4 10a8 8 0 1 1 2 8M4 4v6h6"/>',plus:'<path d="M12 5v14M5 12h14"/>',card:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M6 15h4"/>',bell:'<path d="M4 17h16l-2-3V9a6 6 0 0 0-12 0v5ZM10 21h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};
const icon=(key,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[key]||icons.spark}</svg>`;
const safe=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}),storageKey='santas-lookbook-v1';
const defaults={name:'Charlie',stores:stores.map(s=>s.id),excluded:[],wishes:[],note:'',letter:null};
function readState(){try{return {...structuredClone(defaults),...JSON.parse(localStorage.getItem(storageKey))};}catch{return structuredClone(defaults);}}
const state=readState(),app=document.getElementById('app'),dialog=document.getElementById('dialog'),reducedMotion=matchMedia('(prefers-reduced-motion: reduce)'),smallScreen=matchMedia('(max-width: 700px)');
const name=()=>safe(state.name.trim()||'Christmas explorer'),findGift=id=>gifts.find(g=>g.id===id),eligible=()=>gifts.filter(g=>state.stores.includes(g.store)),curated=()=>eligible().filter(g=>!state.excluded.includes(g.id)),wished=()=>curated().filter(g=>state.wishes.includes(g.id));
const plural=(n,w)=>`${n} ${n===1?w:w==='wish'?'wishes':w.endsWith('discovery')?w.slice(0,-1)+'ies':w+'s'}`,thumbnail=g=>g.thumb?sceneThumbnail(g):`<img src="assets/${g.id}.webp" alt="" width="160" height="160">`,announce=text=>document.getElementById('status').textContent=text;
let page='parent',bookIndex=0,model=null,modelZoom=false,activeTrigger=null,soundEnabled=false,audioContext=null,sceneTimer=null,sendTimers=[],snowBurst=0,turning=false;
const parentPages=new Set(['parent','setup','inbox','delivery']);
const uiButton=(action,label,key,cls='')=>`<button class="button ${cls}" data-action="${action}">${key?icon(key):''}<span>${label}</span></button>`;
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{announce('Changes will last for this visit. Browser storage is unavailable.');}}
function chrome(){const parent=parentPages.has(page);document.body.dataset.page=page;document.body.dataset.mode=parent?'parent':'kid';document.getElementById('chrome').innerHTML=`<button class="wordmark" data-action="${parent?'parent':'cover'}" aria-label="Eve home">eve<span>✦</span></button><span class="chrome-caption">${parent?'A LITTLE CHRISTMAS MAGIC':`${name().toUpperCase()}’S CHRISTMAS STORY`}</span><div class="chrome-right">${parent?'<span class="private-label">Private preview</span>':!['sent','sending'].includes(page)?`<button class="wish-counter" data-action="wishes" aria-label="My wishes, ${wished().length}">${icon('heart',17)}<span>${wished().length}</span></button>`:''}<button class="icon-button sound-toggle" data-action="sound" aria-label="${soundEnabled?'Turn sound off':'Turn sound on'}" aria-pressed="${soundEnabled}">${icon('sound',18)}${!soundEnabled?'<i></i>':''}</button>${!parent?`<button class="icon-button" data-action="parent-gate" aria-label="Grown-ups">${icon('lock',17)}</button>`:''}</div>`;const dock=document.getElementById('dock');dock.hidden=!parent;dock.innerHTML=[['parent','Your world','globe'],['setup','The book','book'],['inbox','Santa mail','mail'],['delivery','Under the tree','bag']].map(([a,l,k])=>`<button data-action="${a}" ${page===a?'aria-current="page"':''}>${icon(k,21)}<span>${l}</span>${a==='inbox'&&getLetter()?'<i class="notification-dot"></i>':''}</button>`).join('');}
function render({focus=false}={}){clearTimeout(sceneTimer);chrome();const views={parent:worldView,setup:setupView,inbox:eveInboxView,delivery:eveDeliveryView,cover:coverView,catalog:bookView,wishes:wishesView,letter:letterView,sending:sendingView,sent:sentView};app.innerHTML=(views[page]||worldView)();if(focus)requestAnimationFrame(()=>app.querySelector('h1')?.focus({preventScroll:true}));if(page==='sending')playSendSequence();}
function go(next){if(page==='letter')storeNote();clearSendTimers();closeModal();dismissToast();page=next;turning=false;render({focus:true});scrollTo({top:0,behavior:'instant'});}
function worldView(){const letter=getLetter();return `<section class="home-scene"><div class="home-copy"><span class="eyebrow">YOUR FAMILY’S CHRISTMAS</span><h1 tabindex="-1">Keep a little<br><em>wonder.</em></h1><p>A world made for ${name()}.<br>A moment you’ll keep for yourself.</p><button class="text-link" data-action="setup">Make it theirs ${icon('arrow',17)}</button></div><button class="globe-touch" data-action="snow" aria-label="Shake the snow globe"><span class="orbit-dot"></span><span class="globe-whisper">Give the world a little shake</span></button><div class="scene-note"><span class="tiny-star">✦</span><span>THE NORTH POLE</span><small>Somewhere, the lights are on.</small></div>${letter?`<button class="arrival-pill" data-action="inbox"><span class="mini-envelope">${icon('mail',20)}</span><span>A little letter has arrived<small>From ${safe(letter.name)}, with love</small></span>${icon('arrow',16)}</button>`:''}<div class="enter-story"><span class="eyebrow">${curated().length?`${plural(curated().length,'little discovery')} inside`:'A story waiting to be made'}</span><button class="story-button" data-action="enter" ${!curated().length?'disabled':''}>Open ${name()}’s world ${icon('arrow',19)}</button><span class="tiny-caption">A story to explore together</span></div></section>`;}
function sheetHead(eye,title,sub){return `<header class="sheet-head"><div><span class="eyebrow">${eye}</span><h1 tabindex="-1">${title}</h1><p>${sub}</p></div><button class="icon-button" data-action="parent" aria-label="Close parent panel">${icon('close')}</button></header>`;}
function setupView(){return `<section class="sheet setup-sheet">${sheetHead('BEHIND THE MAGIC','Make it theirs.','You choose the possibilities. They discover the wonder.')}<div class="setup-layout"><aside class="setup-settings"><label class="field-label" for="child-name">A story for</label><div class="name-input"><input id="child-name" maxlength="28" value="${safe(state.name)}" autocomplete="off" aria-label="Child’s first name">${icon('spark',21)}</div><p class="muted small">Their name is woven into the story and their letter to Santa.</p><div class="section-label">THE STORES IN THEIR WORLD</div><div class="store-list">${stores.map(s=>`<label class="store-choice"><span class="store-symbol ${s.id}">${icon(s.mark,21)}</span><span><strong>${s.name}</strong><small>${s.detail}</small></span><input type="checkbox" data-store="${s.id}" ${state.stores.includes(s.id)?'checked':''} aria-label="Include ${s.name}"><span class="toggle" aria-hidden="true"></span></label>`).join('')}</div><div class="quiet-note">${icon('lock',15)}<p>Only your selected gifts appear in the story. Sample catalog and prices.</p></div></aside><div class="curation"><div class="curation-heading"><span class="section-label">THE LITTLE DISCOVERIES</span><span>${curated().length} of ${gifts.length} included</span></div><div class="curation-list">${gifts.map(g=>{const enabled=state.stores.includes(g.store),chosen=enabled&&!state.excluded.includes(g.id);return `<label class="curation-row ${!enabled?'unavailable':''}">${thumbnail(g)}<span class="gift-meta"><small>${getStore(g.store).name} · Ages ${g.age}</small><strong>${g.name}</strong><span>${g.short}</span></span><span class="gift-price">${money.format(g.price)}</span><input type="checkbox" data-curate="${g.id}" aria-label="Include ${g.name}" ${chosen?'checked':''} ${!enabled?'disabled':''}><span class="check-ui">${icon('check',13)}</span></label>`;}).join('')}</div></div></div><div class="sheet-bottom"><span>${curated().length?`${plural(curated().length,'discovery')}. One very special story.`:'Choose at least one gift to open their world.'}</span><button class="button primary" data-action="enter" ${!curated().length?'disabled':''}>Enter ${name()}’s world ${icon('arrow',18)}</button></div></section>`;}
function eveInboxView(){const letter=getLetter(),items=getItems(letter),picks=letter?selectedItems(letter):[],order=getOrder(letter);if(!letter)return `<section class="sheet">${sheetHead('SANTA MAIL','A little anticipation.','Their letter will arrive here, after a trip to the North Pole.')}<div class="empty-state"><div class="large-seal">${icon('mail',40)}</div><h2>The best mail<br>is still handwritten.</h2><p>Open their world, let them explore, and meet back here when their wishes take flight.</p>${uiButton('enter','Open their story','arrow','primary')}<button class="text-link" data-action="demo-letter">Or explore a sample letter</button></div><div class="prototype-note">Private prototype · Saved in this browser</div></section>`;return `<section class="sheet mail-sheet">${sheetHead('SANTA MAIL',`${safe(letter.name)} dreamed a little.`,`${plural(items.length,'wish')}, straight from the heart.`)}<div class="mail-layout"><div class="mail-left"><div class="letter-paper"><span class="postmark">NORTH POLE<br><b>✦</b> EXPRESS</span><small>Dear Santa,</small><p>${safe(letter.note?.replace(/^Dear Santa,? */i,'')||'Here are a few things I have been dreaming about. Thank you for a little Christmas magic!')}</p><span>With love,<br><em>${safe(letter.name)}</em></span></div><div class="wish-review-heading"><span class="section-label">WHAT THEY WISHED FOR</span><span>All wishes ${dollars(totalCents(items))}</span></div><div class="buy-list">${items.map(g=>`<label class="buy-row ${picks.includes(g)?'':'removed'}">${thumbnail(g)}<span><strong>${g.name}</strong><small>${getStore(g.store).name}</small></span><b>${money.format(g.price)}</b><input type="checkbox" data-cart="${g.id}" aria-label="Buy ${g.name}" ${picks.includes(g)?'checked':''} ${order?'disabled':''}><span class="check-ui">${icon('check',13)}</span></label>`).join('')}</div><p class="muted small">Uncheck a gift to leave it out. Their original wishes stay safe.</p></div><aside class="checkout"><span class="eyebrow">YOUR CHRISTMAS, TAKEN CARE OF</span><h2>${order?'One less thing.<br>More time together.':'A little less planning.<br>A little more presence.'}</h2><div class="total-block"><span>${order?'Demo order total':'Selected gifts'}</span><strong>${dollars(order?order.total:totalCents(picks))}</strong><small>${plural(order?order.items.length:picks.length,'gift')} · ${order?'Demo order placed':'Estimated item subtotal'}</small></div><div class="checkout-divider"></div><button class="payment-card ${commerce.payment?'ready':''}" data-action="payment-sheet"><span class="card-chip">${icon('card',25)}</span><span><strong>${commerce.payment?'Eve sample card':'Prepare your payment'}</strong><small>${commerce.payment?'•••• 4242 · Ready for demo checkout':'Use a sample card for this preview'}</small></span>${icon(commerce.payment?'check':'plus',18)}</button>${order?uiButton('delivery','Follow the magic','arrow','primary wide'):`<button class="button primary wide" data-action="demo-order" ${!commerce.payment||!picks.length?'disabled':''}>Buy selected gifts · ${dollars(totalCents(picks))} ${icon('arrow',18)}</button>`}<p class="prototype-note">Demo checkout. Nothing is purchased or charged. Tax and shipping are not included.</p></aside></div></section>`;}
function eveDeliveryView(){const packages=allPackages(),arrived=packages.filter(p=>p.stage===5).length,delayed=packages.filter(p=>p.stage===2).length,receipts=packages.filter(p=>p.receipt).length,visible=packages.filter(p=>deliveryFilter==='all'||deliveryFilter==='active'&&p.stage<5||deliveryFilter==='delayed'&&p.stage===2||deliveryFilter==='delivered'&&p.stage===5);return `<section class="sheet delivery-sheet">${sheetHead('UNDER THE TREE',packages.length?'The magic is on its way.':'A place for every present.',packages.length?`${arrived} of ${packages.length} packages home${delayed?` · ${plural(delayed,'delay')} to keep an eye on`:'. We’ll keep the details here.'}`:'Every receipt, every delivery, a little less to remember.')}<div class="delivery-layout"><div class="journeys">${packages.length?`<div class="delivery-summary"><div class="tree-progress" style="--progress:${arrived/packages.length*100}%">${icon('bag',27)}<span>${arrived}/${packages.length}</span></div><div><strong>${arrived===packages.length?'All home for the holidays.':'Getting closer to Christmas.'}</strong><small>${arrived===packages.length?'Everything in this demo has arrived.':delayed?'A weather delay has changed an arrival date.':'Your gifts are making their way home.'}</small></div><button class="button secondary small" data-action="advance-delivery" ${arrived===packages.length?'disabled':''}>Advance demo ${icon('arrow',15)}</button></div><div class="segmented" role="group" aria-label="Filter packages">${[['all','All'],['active','On the way'],['delayed','Delayed'],['delivered','Home']].map(([id,label])=>`<button data-action="delivery-filter" data-filter="${id}" aria-pressed="${deliveryFilter===id}">${label}</button>`).join('')}</div><div class="journey-list">${visible.length?visible.map(evePackage).join(''):'<div class="inline-empty">No packages in this chapter.</div>'}</div>`:`<div class="empty-state compact"><div class="large-seal">${icon('bag',36)}</div><h2>First, a wish.<br>Then, a little magic.</h2><p>Choose the gifts you’d like from their letter to start a demo order.</p>${uiButton('inbox','Open Santa mail','arrow','primary')}</div>`}</div><aside class="delivery-assistant"><span class="agent-orb">✦</span><span class="eyebrow">THE QUIET LITTLE HELPERS</span><h2>We’ll remember<br>the details.</h2><p>Receipts sorted by store. Tracking pulled into one place. A nudge at just the right moment.</p><button class="button secondary wide" data-action="demo-email" ${!packages.length?'disabled':''}>${icon('mail',17)} Scan sample inbox</button><button class="text-link receipt-download" data-action="download-receipts" ${!receipts?'disabled':''}>${icon('download',16)} ${receipts?`Download ${plural(receipts,'receipt')}`:'Receipts will appear here'}</button><div class="assistant-rule"></div><label class="notification-control"><span>${icon('bell',17)} Delivery nudges</span><input type="checkbox" data-notices ${commerce.notices?'checked':''}><span class="toggle"></span></label><span class="small muted">Shipped. One day away. At your door.</span><div class="activity-feed">${commerce.activity.length?commerce.activity.slice(0,3).map(a=>`<div><i class="activity-dot ${shipmentStates[a.stage].tone}"></i><span><strong>${shipmentStates[a.stage].name}</strong><small>${getStore(a.store).name} · ${prettyDate(a.date)}</small></span></div>`).join(''):'<p class="small muted">Your delivery moments will appear here.</p>'}</div><p class="prototype-note">Sample emails and in-app alerts. No email account, retailer, or push service is connected.</p></aside></div></section>`;}
function evePackage(p){const s=shipmentStates[p.stage],shop=getStore(p.store);return `<button class="journey" data-action="delivery-details" data-id="${p.id}" aria-label="Track ${shop.name} package ${p.id}"><span class="journey-top"><span class="store-symbol ${shop.id}">${icon(shop.mark)}</span><span><strong>${shop.name}</strong><small>${p.items.map(id=>findGift(id).name).join(' · ')}</small></span><span class="ship-badge ${s.tone}">${s.name}</span></span><span class="journey-path"><i style="width:${Math.max(5,p.stage/5*100)}%"></i></span><span class="journey-bottom"><span>${p.stage===5?'Arrived':'Arriving'} <strong>${prettyDate(p.eta)}</strong>${p.eta!==p.originalEta&&p.stage<5?` <s>${prettyDate(p.originalEta)}</s>`:''}</span><span>${p.carrier} ${icon('arrow',15)}</span></span></button>`;}
const spreads=[{art:'workshop-spread',title:'The Toymaker’s Workshop',line:'Pip left the lights on. And something wonderful on the workbench.',toys:[{id:'tiles',x:23,y:51,w:40,h:52},{id:'train',x:77,y:53,w:43,h:39}]},{art:'cabin-spread',title:'The Cozy Christmas Cabin',line:'Some wishes are made of colors. Others are made for cuddles.',toys:[{id:'bunny',x:22,y:54,w:33,h:58},{id:'art',x:77,y:55,w:39,h:47}]},{art:'starlight-spread',title:'Under the Northern Lights',line:'The world gets bigger when you follow a little curiosity.',toys:[{id:'telescope',x:25,y:52,w:44,h:57},{id:'truck',x:75,y:62,w:41,h:49}]}];
function chapters(){const ids=curated().map(g=>g.id);return spreads.flatMap(s=>smallScreen.matches?s.toys.filter(t=>ids.includes(t.id)).map(t=>({...s,toys:[t],leaf:t.x<50?'left':'right'})):s.toys.some(t=>ids.includes(t.id))?[s]:[]);}
function coverView(){return `<section class="cover-scene"><div class="cover-aurora"></div><div class="cover-intro"><span class="eyebrow">A SECRET FROM THE NORTH POLE</span><h1 tabindex="-1">${name()},<br><em>we’ve been waiting.</em></h1><p>There’s a world tucked inside this book.<br>And a little magic tucked inside you.</p><button class="story-button" data-action="open-book">Let’s find it ${icon('arrow',19)}</button><span class="tiny-caption">Touch a toy. Turn a page. Make a wish.</span></div><button class="storybook-cover" data-action="open-book" aria-label="Open ${name()}’s Christmas story"><span class="book-border"></span><span class="cover-small">THE NORTH POLE PRESS</span><span class="cover-star">✦</span><span class="cover-title">A little<br>Christmas<br><em>wonder.</em></span><span class="cover-flourish">☾</span><span class="cover-dedication">A story for ${name()}</span><span class="cover-year">CHRISTMAS · ${new Date().getFullYear()}</span></button><div class="cover-ground"></div></section>`;}
function bookView(){const all=chapters();if(!all.length)return `<div class="empty-state child-empty"><h1 tabindex="-1">A story is being made.</h1><p>A grown-up can add a few discoveries to your book.</p>${uiButton('parent-gate','Ask a grown-up','lock','gold')}</div>`;bookIndex=Math.min(bookIndex,all.length-1);const ch=all[bookIndex],ids=curated().map(g=>g.id);return `<section class="book-scene"><header class="chapter-heading"><span class="eyebrow">CHAPTER ${String(bookIndex+1).padStart(2,'0')} OF ${String(all.length).padStart(2,'0')}</span><h1 tabindex="-1">${ch.title}</h1><p>${ch.line}</p></header><div class="book-stage"><div class="open-book ${ch.leaf?'single-leaf':''}" id="open-book" data-leaf="${ch.leaf||'both'}"><img class="spread-art" src="assets/${ch.art}.webp" alt="${ch.title}: an illustrated Christmas scene with toys to discover"><div class="paper-grain"></div>${!ch.leaf?'<div class="book-gutter"></div>':''}${ch.toys.map(t=>{if(!ids.includes(t.id))return `<div class="quiet-leaf ${t.x<50?'left':'right'}"><span>✦</span><h2>A little quiet.<br>A little wonder.</h2><p>There is more magic on the next page.</p></div>`;const g=findGift(t.id);return `<button class="toy-hotspot ${state.wishes.includes(g.id)?'is-wished':''}" data-action="gift" data-id="${g.id}" style="--x:${ch.leaf?(t.x%50)*2:t.x}%;--y:${t.y}%;--w:${ch.leaf?t.w*2:t.w}%;--h:${t.h}%" aria-label="Explore ${g.name}"><span class="toy-pin">${icon(state.wishes.includes(g.id)?'heart':'plus',18)}</span><span class="toy-label">${g.name} ${icon('arrow',14)}</span></button>`;}).join('')}<span class="page-number">${bookIndex*2+1}</span><span class="page-number right">${bookIndex*2+2}</span></div></div><div class="book-controls"><button class="icon-button" data-action="prev-page" aria-label="Previous page" ${bookIndex===0?'disabled':''}>${icon('back',23)}</button><span class="book-hint">Touch a toy.<em> Find a little wonder.</em></span><div class="chapter-dots">${all.map((s,i)=>`<button data-action="book-page" data-index="${i}" aria-label="Chapter ${i+1}: ${s.title}" ${i===bookIndex?'aria-current="page"':''}></button>`).join('')}</div><button class="icon-button" data-action="${bookIndex===all.length-1?'wishes':'next-page'}" aria-label="${bookIndex===all.length-1?'Open my wishes':'Next page'}">${icon(bookIndex===all.length-1?'heart':'arrow',23)}</button></div><button class="child-letter-link" data-action="wishes">${plural(wished().length,'wish')} tucked away ${icon('heart',14)}</button></section>`;}
function wishesView(){const items=wished();return `<section class="wish-scene"><div class="wish-heading"><span class="eyebrow">LITTLE THINGS. BIG DREAMS.</span><h1 tabindex="-1">Your pocketful<br>of <em>wishes.</em></h1><p>${items.length?'Every one has a story. Which will you tell Santa?':'Find something that makes your imagination light up.'}</p></div><div class="wish-collection">${items.length?items.map((g,i)=>`<article class="wish-keepsake" style="--tilt:${i%2?3:-3}deg;--i:${i}"><button data-action="gift" data-id="${g.id}" aria-label="Explore ${g.name}">${thumbnail(g)}<span>${g.name}</span></button><button class="remove-wish" data-action="remove-wish" data-id="${g.id}" aria-label="Remove ${g.name}">${icon('close',14)}</button><span class="keepsake-star">✦</span></article>`).join(''):'<div class="empty-wish">✦</div>'}</div><div class="wish-actions">${uiButton('catalog','Keep exploring','back','ghost')}${items.length?uiButton('letter','Write to Santa','arrow','gold'):''}</div></section>`;}
function letterView(){return `<section class="letter-scene"><div class="letter-intro"><span class="eyebrow">ONE LAST LITTLE THING</span><h1 tabindex="-1">The best part<br>is <em>you.</em></h1><p>Tell Santa what you’re dreaming about.<br>Or something you’re proud of.<br>He loves those stories, too.</p><span class="letter-wishes">${wished().map(g=>`<span>${thumbnail(g)}</span>`).join('')}</span><span class="tiny-caption">${plural(wished().length,'wish')} folded into your letter</span><button class="text-link light" data-action="wishes">${icon('back',16)} Back to your wishes</button></div><div class="writing-paper"><div class="paper-stamp">NORTH POLE<br><span>✦</span><small>EXPRESS POST</small></div><label for="santa-note">Dear Santa,</label><textarea id="santa-note" maxlength="700" placeholder="This Christmas, I’ve been dreaming about…" aria-label="Your note to Santa">${safe(state.note)}</textarea><div class="note-toolbar"><button class="dictate-button" data-action="dictate">${icon('mic',16)} Try a voice note</button><span id="note-count">${state.note.length}/700</span></div><div class="letter-signature">With love,<strong>${name()}</strong></div><button class="seal-button" data-action="seal" ${!wished().length?'disabled':''}><span class="wax-seal">✦</span><span>Seal it with a little magic<small>Send my wishes to Santa</small></span>${icon('arrow',19)}</button></div></section>`;}
function sendingView(){return `<section class="send-scene" id="send-scene" data-step="fold"><img class="launch-art" src="assets/launch.webp" alt="A golden letter taking flight above the snowy North Pole"><div class="send-vignette"></div><div class="flying-letter"><span>To Santa</span><i>✦</i><small>From ${name()}</small></div><div class="magic-trail"></div><div class="send-stars">${Array.from({length:35},(_,i)=>`<i style="--a:${i*10.3}deg;--d:${150+(i%7)*75}px;--t:${i%5*.07}s"></i>`).join('')}</div><div class="send-caption"><span class="eyebrow">NORTH POLE EXPRESS</span><h1 tabindex="-1" id="send-title">A wish becomes a letter.</h1><p id="send-subtitle">A letter becomes a little bit of magic.</p></div><button class="skip-finale" data-action="finish-send">Skip animation ${icon('arrow',15)}</button></section>`;}
function sentView(){return `<section class="sent-scene"><img class="sent-art" src="assets/launch.webp" alt="Santa’s sleigh in a glowing winter sky"><div class="sent-glow"></div><div class="sent-message"><span class="sent-seal">${icon('check',30)}</span><span class="eyebrow">DELIVERED TO THE NORTH POLE</span><h1 tabindex="-1">Somewhere, Santa<br>is <em>smiling.</em></h1><p>Your letter made it, ${name()}.<br>Now the best kind of waiting begins.</p><span class="sent-signature">Keep a little wonder. ✦</span><div class="sent-actions">${uiButton('catalog','Wander a little longer','book','ghost')}${uiButton('parent-gate','Back to the family','arrow','gold')}</div><small>Your wishes are tucked safely into Santa mail.</small></div></section>`;}
function modalShell(content,cls=''){closeModal();activeTrigger=document.activeElement;dialog.className=cls;dialog.innerHTML=`<button class="dialog-close icon-button" data-action="close" aria-label="Close">${icon('close')}</button>${content}`;dialog.showModal();}
function closeModal(){if(model){model.close();model=null;}if(dialog.open){dialog.close();activeTrigger?.focus?.();}}
function showGift(id){const g=findGift(id);if(!g||!curated().includes(g))return;const selected=state.wishes.includes(id);modalShell(`<div class="toy-showroom"><div class="toy-canvas-wrap"><span class="model-caption">A LITTLE CLOSER TO THE MAGIC</span><canvas id="gift-model" role="img" aria-label="Interactive three-dimensional model of ${g.name}. Drag to rotate, or use the rotate buttons."></canvas><span class="drag-hint">Drag to discover every side</span><div class="model-tools"><button class="icon-button" data-action="rotate-left" aria-label="Rotate toy left">${icon('back',18)}</button><button class="icon-button" data-action="model-reset" aria-label="Reset toy view">${icon('rotate',18)}</button><button class="icon-button" data-action="model-zoom" aria-label="Zoom toy" aria-pressed="false">${icon('plus',18)}</button><button class="icon-button" data-action="rotate-right" aria-label="Rotate toy right">${icon('arrow',18)}</button></div><small class="model-disclosure">Stylized 3D preview</small></div><div class="toy-detail"><span class="eyebrow">${g.category} · Ages ${g.age}</span><h2 id="dialog-title">${g.name}</h2><p class="toy-tagline">${g.short}</p><p>${g.detail}</p><div class="inside-toy"><small>THE LITTLE DETAILS</small><span>${g.inside}</span></div><div class="play-prompt">${icon('spark',18)}<p>${g.play}</p></div><button class="button gold wide" data-action="wish" data-id="${g.id}" aria-pressed="${selected}">${icon(selected?'check':'heart',19)} ${selected?'Tucked into my wishes':'Add to my wishes'}</button><button class="text-link" data-action="close">Back to the story ${icon('arrow',16)}</button></div></div>`,'gift-dialog');modelZoom=false;requestAnimationFrame(()=>{const canvas=document.getElementById('gift-model');if(canvas)model=mountGiftModel(canvas,id);});}
function toggleWish(id){if(!curated().some(g=>g.id===id))return;const adding=!state.wishes.includes(id);state.wishes=adding?[...state.wishes,id]:state.wishes.filter(x=>x!==id);save();const b=dialog.querySelector('[data-action="wish"]');if(b){b.innerHTML=`${icon(adding?'check':'heart',19)} ${adding?'Tucked into my wishes':'Add to my wishes'}`;b.setAttribute('aria-pressed',adding);b.classList.remove('wish-pop');void b.offsetWidth;b.classList.add('wish-pop');}chrome();if(adding){playChime();snowBurst=1.5;}announce(adding?'A wish tucked away.':'Wish removed.');}
function parentGate(){modalShell(`<div class="gate-content"><span class="eyebrow">FOR THE MAGIC MAKERS</span><h2 id="dialog-title">A little grown-up<br>business.</h2><p>The wishes and surprises live on the other side.</p><button class="button primary wide" data-action="return-parent">I’m a grown-up ${icon('arrow',18)}</button><button class="text-link" data-action="close">Stay in the story</button><small>Preview mode switch</small></div>`,'gate-dialog');}
function paymentSheet(){modalShell(`<div class="gate-content"><span class="eyebrow">READY WHEN YOU ARE</span><h2 id="dialog-title">One small step.<br>Everything ready.</h2><div class="sample-bank-card"><span>eve <i>✦</i></span><b>•••• &nbsp; •••• &nbsp; •••• &nbsp; 4242</b><small>SAMPLE CARD · DEMO ONLY</small></div><p>This card demonstrates a saved payment method. No payment information is collected.</p><button class="button primary wide" data-action="confirm-payment">${commerce.payment?'Keep sample card':'Use sample card'} ${icon('check',18)}</button></div>`,'gate-dialog');}
function packageDetail(id){const p=allPackages().find(p=>p.id===id);if(!p)return;modalShell(`<div class="gate-content tracking-content"><span class="eyebrow">${p.carrier} · ${safe(p.tracking||'TRACKING PENDING')}</span><h2 id="dialog-title">${getStore(p.store).name}<br><em>A little closer.</em></h2><p>${p.items.map(id=>findGift(id).name).join(' · ')}</p><ol class="track-timeline">${[...p.history].reverse().map(h=>`<li><span class="timeline-dot"></span><strong>${shipmentStates[h.stage].name}</strong><span>${prettyDate(h.date)}</span><p>${shipmentStates[h.stage].description}</p></li>`).join('')}</ol>${uiButton('close','Done',null,'primary wide')}</div>`,'gate-dialog');}
function storeNote(){const input=document.getElementById('santa-note');if(input){state.note=input.value.slice(0,700);save();}}
function dictate(){storeNote();modalShell(`<div class="gate-content"><div class="voice-orb">${icon('mic',35)}</div><span class="eyebrow">A LITTLE VOICE. A BIG WISH.</span><h2 id="dialog-title">Say it your way.</h2><div class="voice-wave">${Array.from({length:17},(_,i)=>`<i style="--h:${12+(i*17%38)}px;--d:${i*.06}s"></i>`).join('')}</div><p>“Dear Santa, I’d love something to build and a little adventure. I’ll leave a carrot for the reindeer!”</p><button class="button primary wide" data-action="use-voice">Use this sample voice note ${icon('check',18)}</button><small>Voice-to-text concept. This preview uses a sample and does not access your microphone.</small></div>`,'gate-dialog');}
function sealLetter(){if(!wished().length)return;storeNote();state.letter={id:`eve-${Date.now()}`,name:state.name.trim()||'Christmas explorer',gifts:wished().map(g=>g.id),note:state.note,date:new Date().toISOString()};save();go('sending');}
function clearSendTimers(){sendTimers.forEach(clearTimeout);sendTimers=[];}
function playSendSequence(){clearSendTimers();if(reducedMotion.matches){sendTimers.push(setTimeout(()=>go('sent'),800));return;}const step=(delay,key,title,sub)=>sendTimers.push(setTimeout(()=>{const scene=document.getElementById('send-scene');if(!scene)return;scene.dataset.step=key;document.getElementById('send-title').textContent=title;document.getElementById('send-subtitle').textContent=sub;playChime(key==='arrive'?2:1);snowBurst=3;},delay));playChime();step(1900,'lift','Some wishes deserve wings.','Up past the rooftops. Out beyond the stars.');step(4100,'flight','Hold on to the wonder.','The North Pole is closer than you think.');step(6600,'arrive','One very special delivery.','Your wishes have found their way.');sendTimers.push(setTimeout(()=>go('sent'),9000));}
function turnPage(index){if(turning||index<0||index>=chapters().length||index===bookIndex)return;if(reducedMotion.matches){bookIndex=index;render({focus:true});return;}turning=true;document.getElementById('open-book')?.classList.add(index>bookIndex?'turn-forward':'turn-back');playChime(.4);sceneTimer=setTimeout(()=>{bookIndex=index;turning=false;render({focus:true});app.querySelector('.open-book')?.classList.add('page-arrived');},420);}
function playChime(level=1){if(!soundEnabled)return;try{audioContext ||=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();[523.25,659.25,783.99,1046.5,1318.5].forEach((freq,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.12;o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.035*level,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+1.5);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+1.5);});}catch{soundEnabled=false;chrome();}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;if(parentPages.has(a)||['catalog','wishes','letter','cover'].includes(a)){go(a);return;}const actions={enter:()=>{if(!curated().length)return;bookIndex=0;go('cover');playChime();},'open-book':()=>{bookIndex=0;go('catalog');playChime();},snow:()=>{snowBurst=5;const w=document.getElementById('world');w.classList.remove('shaken');void w.offsetWidth;w.classList.add('shaken');playChime();},sound:()=>{soundEnabled=!soundEnabled;chrome();playChime();},close:()=>{closeModal();if(['catalog','wishes'].includes(page))render();},gift:()=>showGift(id),wish:()=>toggleWish(id),'remove-wish':()=>{state.wishes=state.wishes.filter(x=>x!==id);save();render();announce('Wish removed.');},'next-page':()=>turnPage(bookIndex+1),'prev-page':()=>turnPage(bookIndex-1),'book-page':()=>turnPage(Number(b.dataset.index)),'parent-gate':parentGate,'return-parent':()=>go('inbox'),'rotate-left':()=>model?.turn(-1),'rotate-right':()=>model?.turn(1),'model-reset':()=>{model?.reset();modelZoom=false;dialog.querySelector('[data-action="model-zoom"]')?.setAttribute('aria-pressed','false');},'model-zoom':()=>{modelZoom=!modelZoom;model?.zoom(modelZoom);b.setAttribute('aria-pressed',modelZoom);},dictate,'use-voice':()=>{state.note='I’d love something to build and a little adventure. I’ll leave a carrot for the reindeer!';save();closeModal();render();document.getElementById('santa-note')?.focus();},seal:sealLetter,'finish-send':()=>go('sent'),'demo-letter':showSampleLetter,'demo-payment':paymentSheet,'payment-sheet':paymentSheet,'confirm-payment':()=>{closeModal();readyPayment();},'demo-order':()=>{placeOrder();playChime();},'demo-email':importSampleMail,'download-receipts':downloadReceipts,'advance-delivery':advanceDeliveries,'delivery-filter':()=>filterDeliveries(b),'delivery-details':()=>packageDetail(id)};actions[a]?.();});
document.addEventListener('change',e=>{const i=e.target;if(i.matches('[data-store]')){state.stores=i.checked?[...new Set([...state.stores,i.dataset.store])]:state.stores.filter(id=>id!==i.dataset.store);save();render();app.querySelector(`[data-store="${i.dataset.store}"]`)?.focus();}if(i.matches('[data-curate]')){state.excluded=i.checked?state.excluded.filter(id=>id!==i.dataset.curate):[...new Set([...state.excluded,i.dataset.curate])];save();render();app.querySelector(`[data-curate="${i.dataset.curate}"]`)?.focus();}if(i.matches('[data-cart]'))changeCart(i);if(i.matches('[data-notices]')){commerce.notices=i.checked;saveCommerce();announce(i.checked?'Demo delivery nudges on.':'Demo delivery nudges paused.');}});
document.addEventListener('input',e=>{if(e.target.id==='child-name'){state.name=e.target.value;save();const cta=app.querySelector('.sheet-bottom .button');if(cta)cta.innerHTML=`Enter ${name()}’s world ${icon('arrow',18)}`;}if(e.target.id==='santa-note'){state.note=e.target.value;save();document.getElementById('note-count').textContent=`${state.note.length}/700`;}});
dialog.addEventListener('cancel',()=>{model?.close();model=null;if(['catalog','wishes'].includes(page))render();});dialog.addEventListener('click',e=>{if(e.target===dialog){closeModal();if(['catalog','wishes'].includes(page))render();}});
document.addEventListener('keydown',e=>{if(dialog.open||e.target.matches('input,textarea'))return;if(page==='catalog'){if(e.key==='ArrowRight')turnPage(bookIndex+1);if(e.key==='ArrowLeft')turnPage(bookIndex-1);}if(e.key==='Escape'&&parentPages.has(page)&&page!=='parent')go('parent');});smallScreen.addEventListener('change',()=>{if(page==='catalog'){bookIndex=0;render();}});
function mountSnow(){const canvas=document.getElementById('snow'),ctx=canvas.getContext('2d');if(!ctx)return;let width=0,height=0,particles=[],last=0;function resize(){width=innerWidth;height=innerHeight;const d=Math.min(devicePixelRatio||1,1.5);canvas.width=width*d;canvas.height=height*d;ctx.setTransform(d,0,0,d,0,0);particles=Array.from({length:width<700?55:115},()=>({x:Math.random()*width,y:Math.random()*height,r:.5+Math.random()*1.7,s:.12+Math.random()*.4,p:Math.random()*6.28}));}function frame(t){const dt=Math.min(t-last,40)/16.67;last=t;ctx.clearRect(0,0,width,height);if(!document.hidden){snowBurst=Math.max(0,snowBurst-.012*dt);for(const p of particles){if(!reducedMotion.matches){p.y+=(p.s+snowBurst*.32)*dt;p.x+=(Math.sin(t*.0004+p.p)*.15+snowBurst*Math.cos(p.p)*1.2)*dt;if(p.y>height)p.y=-5;if(p.x>width)p.x=0;if(p.x<0)p.x=width;}ctx.beginPath();ctx.fillStyle=`rgba(255,239,199,${Math.min(.7,.15+Math.sin(p.p+t*.0007)*.1+snowBurst*.08)})`;ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();}}requestAnimationFrame(frame);}resize();addEventListener('resize',resize);requestAnimationFrame(frame);document.addEventListener('pointermove',e=>{if(page!=='parent'||reducedMotion.matches||e.pointerType==='touch')return;const w=document.getElementById('world');w.style.setProperty('--mx',`${(e.clientX/innerWidth-.5)*7}px`);w.style.setProperty('--my',`${(e.clientY/innerHeight-.5)*5}px`);});}
render();mountSnow();
